query:
// Returning list of maps to satisfy MCP ingestion expectations.
MATCH (u:User {id: 'perf_user_001'})-[:CREATED]->(m:Memory)-[:TAGGED_WITH]->(t:Topic)
WITH t.name AS topic_name, count(m) AS memory_count
RETURN {topic: topic_name, memory_count: memory_count}
ORDER BY memory_count DESC
LIMIT 10
